/*
 * V8 ApiEngine
 * ApiEngineKey: ai_app_build_file
 * Version: v1.0.9
 * Function:
 * - 统一使用 sys_microistore 作为应用主表；mci_ai_app_file 与 mci_ai_app_version 继续保存私有源码和构建版本。
 */

function ok(data, msg) { return { Code: 1, Data: data || null, Msg: msg || '成功' }; }
function fail(msg, data) { return { Code: 0, Data: data || null, Msg: msg || '执行失败' }; }
function text(value, fallback) { return value === null || value === undefined ? (fallback || '') : String(value); }
function isBlank(value) { return text(value).replace(/^\s+|\s+$/g, '') === ''; }
function toArray(value) { var list = []; if (!value || value.length === undefined) return list; for (var i=0;i<value.length;i++) list.push(value[i]); return list; }
function normalizePath(value) {
  var path = text(value).replace(/\\/g,'/').replace(/^\/+|\/+$/g,'');
  var parts = path.split('/'), safe=[];
  for(var i=0;i<parts.length;i++){ if(!parts[i]||parts[i]==='.'||parts[i]==='..') continue; safe.push(parts[i].replace(/[:*?"<>|]/g,'_')); }
  return safe.join('/');
}
function isTextPath(path) {
  var lower=text(path).toLowerCase();
  return /\.(html?|css|scss|sass|less|js|jsx|mjs|cjs|ts|tsx|json|map|xml|txt|md|svg|yaml|yml|toml|ini)$/.test(lower);
}
function currentUser() {
  var user=V8.CurrentUser||{};
  if(!user||isBlank(user.Id)){ var token=V8.Method.GetCurrentToken?V8.Method.GetCurrentToken():null; if(token&&token.CurrentUser) user=token.CurrentUser; }
  return user||{};
}
function getApp(appId) { return V8.FormEngine.GetFormData('sys_microistore',{_Where:[['Id','=',appId]],_PageSize:1}); }
function getService(appKey) { return V8.FormEngine.GetFormData('sys_microiservice',{_Where:[['MsKey','=',appKey]],_PageSize:1}); }
function assertCanEdit(app) {
  var user=currentUser(), level=parseInt(user.Level||0,10);
  if(level>=9999) return;
  if(isBlank(user.Id)||text(app.OwnerUserId)!==text(user.Id)) throw new Error('无权查看或修改该应用编译文件');
}
function publicUrl(path) {
  if(/^https?:\/\//i.test(text(path))) return text(path);
  var result=V8.Method.GetPrivateFileUrl({OsClient:V8.OsClient,FilePathName:path,Limit:false});
  if(!result||result.Code!==1) throw new Error('获取编译文件地址失败：'+path);
  var data=result.Data||{};
  return typeof data==='string'?data:text(data.Url||data.url||data.FileUrl||data.FullPath||data.Path);
}
function findAsset(assets,path) {
  var target=normalizePath(path).toLowerCase();
  for(var i=0;i<assets.length;i++){ if(normalizePath(assets[i].Path||assets[i].RelativePath||assets[i].FileName).toLowerCase()===target) return {Asset:assets[i],Index:i}; }
  return null;
}
var appId=text(V8.Param.AppId);
if(isBlank(appId)) return fail('AppId不能为空');
var appResult=getApp(appId);
if(!appResult||appResult.Code!==1||!appResult.Data) return {Code:2,Data:null,Msg:'AI应用不存在'};
var app=appResult.Data;
try{assertCanEdit(app);}catch(authError){return fail(authError.message);}
var action=text(V8.Param.Action||'List');
if(text(app.AppType)==='MicroService'){
  var serviceResult=getService(app.AppKey);
  if(!serviceResult||serviceResult.Code!==1||!serviceResult.Data) return fail('未找到微服务编译记录');
  var service=serviceResult.Data, assets=[];
  try{assets=toArray(JSON.parse(service.AssetsJson||'[]'));}catch(e){return fail('AssetsJson不是有效JSON');}
  if(action==='List') return ok({Files:assets,HasSource:true,BuildVersion:service.BuildVersion||'',EntryPath:service.EntryPath||'index.html'});
  var path=normalizePath(V8.Param.Path||V8.Param.FilePath);
  var found=findAsset(assets,path);
  if(!found) return {Code:2,Data:null,Msg:'编译文件不存在：'+path};
  if(!isTextPath(path)) return fail('当前文件为二进制文件，仅支持查看文本编译文件');
  if(action==='Get'){
    var response=V8.Http.GetResponse({Url:publicUrl(found.Asset.FilePathName||found.Asset.HdfsPath||found.Asset.FullPath||found.Asset.Url),Timeout:120});
    if(!response||!response.RawBytes) return fail('下载编译文件失败：'+path);
    return ok({Path:path,Content:System.Text.Encoding.UTF8.GetString(response.RawBytes),Size:response.RawBytes.Length,Readonly:false});
  }
  if(action==='Save'){
    var content=text(V8.Param.Content), slash=path.lastIndexOf('/'), dir=slash>-1?path.substring(0,slash):'', fileName=slash>-1?path.substring(slash+1):path;
    var files={}; files[fileName]=V8.Base64.StringToBase64(content);
    var upload=V8.Method.Upload({OsClient:V8.OsClient,Path:'micro-app/'+app.AppKey+'/'+text(service.BuildVersion||'v1.0.0')+(dir?'/'+dir:''),Limit:false,Preview:false,FilesByteBase64:files});
    if(!upload||upload.Code!==1||!upload.Data||!upload.Data.length) return upload||fail('保存编译文件失败');
    var saved=upload.Data[0]||{};
    found.Asset.FilePathName=saved.Path||saved.FilePathName||saved.FilePath||saved.Url;
    found.Asset.FullPath=saved.FullPath||saved.Url||saved.url||'';
    found.Asset.Size=saved.Size||content.length;
    assets[found.Index]=found.Asset;
    var manifest={MsKey:app.AppKey,BuildVersion:service.BuildVersion,EntryPath:service.EntryPath||'index.html',Assets:assets};
    var update=V8.FormEngine.UptFormData('sys_microiservice',{Id:service.Id,AssetsJson:JSON.stringify(assets),AssetManifestJson:JSON.stringify(manifest),AssetCount:assets.length,UpdateTime:DateNow('yyyy-MM-dd HH:mm:ss')});
    if(!update||update.Code!==1) return update||fail('更新微服务编译清单失败');
    return ok({Path:path,Asset:found.Asset},'编译文件已保存');
  }
  return fail('不支持的操作：'+action);
}
var versionResult=V8.FormEngine.GetTableData('mci_ai_app_version',{_Where:[['AppId','=',app.Id]],_OrderBy:'CreateTime',_OrderByType:'DESC',_PageSize:1});
var version=versionResult&&versionResult.Code===1&&versionResult.Data&&versionResult.Data.length?versionResult.Data[0]:null;
if(!version) return fail('未找到应用编译版本');
if(action==='List') return ok({Files:[{Path:'index.html',FileName:'index.html',Size:text(version.BuildLog).length,IsEntry:true}],BuildVersion:version.VersionNo||'',EntryPath:'index.html'});
if(normalizePath(V8.Param.Path||V8.Param.FilePath)!=='index.html') return {Code:2,Data:null,Msg:'编译文件不存在'};
