                        ['RoleId', '=', roleId],
                        ['AND', 'FkId', '=', menuId],
                        ['AND', 'Type', '=', 'Menu']
                    ],
                    _SelectFields: ['Id', 'Permission'],
                    _PageIndex: 1,
                    _PageSize: 1000
                });
